"use strict";(Array.isArray(self.webpackChunkwoocommerce_multivendor_marketplace_docs)?self.webpackChunkwoocommerce_multivendor_marketplace_docs:self.webpackChunkwoocommerce_multivendor_marketplace_docs=[]).push([[9390],{50930(e,t,s){s.r(t),s.d(t,{comp:()=>f,data:()=>g});var n=s(20641);const a=s.p+"assets/img/vendor-staff-list.6d4dfb45.png",i=s.p+"assets/img/add-vendor-staff.9157aceb.png",r=s.p+"assets/img/edit-vedor-staff-setting.340d2f03.png",o=s.p+"assets/img/vendor-staff-delete-modal.c0695803.png",l=s.p+"assets/img/allowed-staff-to-do.258f452c.png",d=s.p+"assets/img/allowed-staff-to-do-2.83d2e37c.png",c={},f=(0,s(66262).A)(c,[["render",function(e,t){return(0,n.uX)(),(0,n.CE)("div",null,t[0]||(t[0]=[(0,n.Fv)('<h1 id="vendor-staff" tabindex="-1"><a class="header-anchor" href="#vendor-staff"><span>Vendor Staff</span></a></h1><p>The <strong>Vendor Staff</strong> feature allows vendors to add sub-users (store managers and team assistants) who can log in and manage the store on their behalf. Vendors can grant per-task permissions for each section (view, add, edit, delete, and more) based on the capabilities allowed by the admin.</p><div class="hint-container tip"><p class="hint-container-title">Store Administration Note</p><p>If you are a marketplace administrator looking to configure global staff settings, maximum staff limits per vendor, delegatable permissions, or manage all vendor staff members, please refer to the <a href="/documentation/admin-staff-setting" target="_blank" rel="noopener noreferrer">Configuration – Staff Settings</a> guide.</p></div><hr><h2 id="why-use-vendor-staff" tabindex="-1"><a class="header-anchor" href="#why-use-vendor-staff"><span>Why Use Vendor Staff?</span></a></h2><p>Running a busy online store often requires teamwork. The Vendor Staff feature provides several practical advantages for sellers:</p><ul><li><strong>Secure Delegation Without Password Sharing</strong>: Vendors do not need to share their master account password with assistants. Each staff member receives their own unique login.</li><li><strong>Granular Permission Control</strong>: Assign precise responsibilities to team members. For example, allow a shipping coordinator to view orders and print invoices without allowing them to delete products or issue refunds.</li><li><strong>Role Specialization</strong>: Create different sub-accounts for different team roles, such as product managers, customer support agents, order fulfillment staff, or designers.</li><li><strong>Financial Privacy</strong>: Staff members cannot view or modify the vendor&#39;s sensitive bank account details, payout settings, or withdrawal records.</li></ul><hr><h2 id="managing-vendor-staff" tabindex="-1"><a class="header-anchor" href="#managing-vendor-staff"><span>Managing Vendor Staff</span></a></h2><p>Vendors can view a list of all their staff members from the Vendor Dashboard by navigating to <strong>Vendor Staff</strong> from the seller menu.</p><p><a class="doc-image-link" href="./assets/vendor-staff-list.png"><img src="'+a+'" alt="Vendor Staff List"></a></p><h3 id="staff-directory-table" tabindex="-1"><a class="header-anchor" href="#staff-directory-table"><span>Staff Directory Table</span></a></h3><p>The main directory table displays the following columns for every registered assistant:</p><ul><li><strong>Name</strong>: The full name of the staff member.</li><li><strong>Email</strong>: The staff member&#39;s registered email address used for signing into their account.</li><li><strong>Access</strong>: A comma-separated list of all marketplace sections and modules the staff member is permitted to access (such as <em>Seller Dashboard, Products, Orders, Transactions, Vacation, Shop Followers, Notifications, My Profile, Ask Admin, Shippings, Admin News</em>).</li><li><strong>Actions</strong>: Operational buttons available for each staff entry: <ul><li><strong>Edit</strong>: Opens the staff settings screen to change the staff member&#39;s name or adjust their permissions.</li><li><strong>Delete</strong>: Permanently removes the staff member and revokes their store access.</li></ul></li></ul><hr><h3 id="adding-a-new-staff-member" tabindex="-1"><a class="header-anchor" href="#adding-a-new-staff-member"><span>Adding a New Staff Member</span></a></h3><p>To add a new staff member, click on the <strong>+Add Vendor Staff</strong> button located at the top right of the staff directory.</p><p><a class="doc-image-link" href="./assets/add-vendor-staff.png"><img src="'+i+'" alt="Add Vendor Staff"></a></p><p>On the <strong>Add Vendor Staff</strong> form, complete the required account details:</p><ol><li><strong>Name</strong>: Enter the staff member&#39;s full name (e.g., <em>Jane Doe</em>). This field is required.</li><li><strong>Email</strong>: Enter their valid email address (e.g., <em>name@example.com</em>). This email is required and serves as their username for logging into the store.</li><li><strong>Choose Permissions</strong>: Review the permission cards below the user details and select the specific tasks this staff member is allowed to perform.</li><li><strong>Save Account</strong>: Click the <strong>Add Vendor Staff</strong> button at the bottom of the page to create the sub-account. To cancel without saving, click <strong>Cancel</strong>.</li></ol><div class="hint-container info"><p class="hint-container-title">Account Login Credentials</p><p>Vendors do not set a password manually when creating a staff account. An automatic email notification is sent to the staff member&#39;s email address with instructions to set up their password and log in.</p></div><hr><h3 id="editing-staff-settings-and-permissions" tabindex="-1"><a class="header-anchor" href="#editing-staff-settings-and-permissions"><span>Editing Staff Settings and Permissions</span></a></h3><p>Vendors can edit existing staff settings and define precise permissions for what the staff member is allowed to do. To edit an assistant, click the <strong>Edit</strong> button next to their name in the staff directory table.</p><p><a class="doc-image-link" href="./assets/edit-vedor-staff-setting.png"><img src="'+r+'" alt="Edit Vendor Staff Setting"></a></p><p>When editing a staff member:</p><ul><li><strong>Name</strong>: Can be updated at any time.</li><li><strong>Email</strong>: This field is locked (read-only) to protect user identity and maintain account security.</li><li><strong>Permissions</strong>: Check or uncheck capability checkboxes across the various permission cards to grant or revoke specific rights.</li><li><strong>Update Changes</strong>: Click the <strong>Update Vendor Staff</strong> button to apply the changes immediately.</li></ul><hr><h3 id="removing-a-staff-member" tabindex="-1"><a class="header-anchor" href="#removing-a-staff-member"><span>Removing a Staff Member</span></a></h3><p>When a team member leaves or no longer requires access, vendors can delete their sub-account directly from the staff directory list:</p><ol><li>Locate the staff member in the table and click the <strong>Delete</strong> button under <strong>Actions</strong>.</li><li>A confirmation modal titled <strong>Remove vendor staff?</strong> will appear.</li></ol><p><a class="doc-image-link" href="./assets/vendor-staff-delete-modal.png"><img src="'+o+'" alt="Remove Vendor Staff Confirmation Modal"></a></p><ol start="3"><li>Review the warning notice: <em>&quot;This vendor staff will lose access to your store. This action cannot be undone.&quot;</em></li><li>Click <strong>Yes, remove</strong> to confirm deletion, or click <strong>Cancel</strong> to keep the staff account.</li></ol><hr><h2 id="granular-permissions-matrix" tabindex="-1"><a class="header-anchor" href="#granular-permissions-matrix"><span>Granular Permissions Matrix</span></a></h2><p>The permissions can be granularly controlled per section (e.g., Products, Orders, Profile) and per action (e.g., view, add, edit, delete). Each module is presented as a distinct card with an interactive <strong>Select all</strong> button on the header for quick configuration.</p><p><a class="doc-image-link" href="./assets/allowed-staff-to-do.png"><img src="'+l+'" alt="Allowed Staff Permissions"></a></p><p><a class="doc-image-link" href="./assets/allowed-staff-to-do-2.png"><img src="'+d+'" alt="Allowed Staff Permissions Continued"></a></p><p>Here is the complete breakdown of all available permission cards and what each capability allows:</p><h3 id="_1-seller-dashboard" tabindex="-1"><a class="header-anchor" href="#_1-seller-dashboard"><span>1. Seller Dashboard</span></a></h3><ul><li><strong>Access New Seller Panel</strong>: Allows logging in and navigating the modern seller dashboard interface.</li><li><strong>Performance</strong>: View store analytics, traffic metrics, and sales conversion figures.</li><li><strong>Reporting</strong>: Access comprehensive store reports and sales summaries.</li><li><strong>Customers</strong>: View customer listings and buyer information.</li><li><strong>Magic AI</strong>: Access built-in AI tools for product copy generation and content assistance.</li><li><strong>General Setting</strong>: Modify general shop configuration preferences.</li><li><strong>Graph Setting</strong>: Adjust dashboard graph display styles and color palettes.</li><li><strong>Site Setting</strong>: Customize storefront appearance preferences.</li></ul><h3 id="_2-products" tabindex="-1"><a class="header-anchor" href="#_2-products"><span>2. Products</span></a></h3><ul><li><strong>View products</strong>: Browse and view all products belonging to the vendor.</li><li><strong>Add product</strong>: Create new products in the vendor catalog.</li><li><strong>Edit product</strong>: Update existing product details, descriptions, prices, and inventory levels.</li><li><strong>Delete product</strong>: Remove products from the vendor&#39;s catalog.</li><li><strong>Publish product</strong>: Publish newly created or edited products live on the marketplace.</li><li><strong>Generate barcodes</strong>: Generate unique barcode labels for products.</li><li><strong>Print barcodes</strong>: Download and print generated product barcodes.</li></ul><h3 id="_3-select-and-sell" tabindex="-1"><a class="header-anchor" href="#_3-select-and-sell"><span>3. Select And Sell</span></a></h3><ul><li><strong>View listing</strong>: Browse existing catalog products available for selling.</li><li><strong>Add product</strong>: Join an existing product listing to offer the vendor&#39;s own price and stock.</li><li><strong>Edit product</strong>: Modify inventory, price, or product condition on assigned listings.</li><li><strong>Delete product</strong>: Remove the vendor&#39;s offer from an existing product listing.</li></ul><h3 id="_4-bulk-upload" tabindex="-1"><a class="header-anchor" href="#_4-bulk-upload"><span>4. Bulk Upload</span></a></h3><ul><li><strong>Normal Products</strong>: Batch upload standard catalog products using CSV data sheets.</li><li><strong>Select And Sell</strong>: Batch upload and map existing marketplace listings via CSV.</li></ul><h3 id="_5-orders" tabindex="-1"><a class="header-anchor" href="#_5-orders"><span>5. Orders</span></a></h3><ul><li><strong>View orders</strong>: View customer orders, ordered items, billing info, and shipping addresses.</li><li><strong>Change order status</strong>: Update order fulfillment statuses (e.g., Processing, Completed).</li><li><strong>Refund order</strong>: Process order refunds for the vendor&#39;s products.</li><li><strong>Print invoice</strong>: Generate and download printable customer invoices or packing slips.</li><li><strong>Schedule pickups</strong>: Book courier pickup appointments for store orders.</li></ul><h3 id="_6-transactions" tabindex="-1"><a class="header-anchor" href="#_6-transactions"><span>6. Transactions</span></a></h3><ul><li><strong>View transaction list</strong>: Review transaction history and balance ledger entries.</li><li><strong>View transaction details</strong>: Open individual transaction records to inspect itemized breakdowns.</li></ul><h3 id="_7-vacation" tabindex="-1"><a class="header-anchor" href="#_7-vacation"><span>7. Vacation</span></a></h3><ul><li><strong>View vacations</strong>: Check current, past, and upcoming store vacation schedules.</li><li><strong>Add vacation</strong>: Schedule a new store closure period with a custom storefront notice.</li><li><strong>Edit vacation</strong>: Modify dates or announcement text on existing vacation schedules.</li><li><strong>Delete vacation</strong>: Remove an existing vacation schedule to reopen the shop early.</li></ul><h3 id="_8-shop-followers" tabindex="-1"><a class="header-anchor" href="#_8-shop-followers"><span>8. Shop Followers</span></a></h3><ul><li><strong>View followers</strong>: See the list of registered customers who follow the vendor&#39;s shop.</li><li><strong>Remove followers</strong>: Remove specific customers from the followers list.</li><li><strong>Send notification to followers</strong>: Send email announcements or promotional updates to followers.</li></ul><h3 id="_9-notifications" tabindex="-1"><a class="header-anchor" href="#_9-notifications"><span>9. Notifications</span></a></h3><ul><li><strong>View notifications</strong>: Check real-time alerts for incoming orders, low stock, and system notices.</li></ul><h3 id="_10-my-profile" tabindex="-1"><a class="header-anchor" href="#_10-my-profile"><span>10. My Profile</span></a></h3><ul><li><strong>View profile</strong>: View public store profile details and settings.</li><li><strong>Edit profile</strong>: Update store biography, avatar, banner image, contact information, and social links.</li></ul><h3 id="_11-ask-admin" tabindex="-1"><a class="header-anchor" href="#_11-ask-admin"><span>11. Ask Admin</span></a></h3><ul><li><strong>View query list</strong>: Browse support inquiries sent to marketplace administrators.</li><li><strong>View query thread</strong>: Open an existing conversation thread to read admin replies.</li><li><strong>Create new query</strong>: Submit a new help ticket or question to the admin team.</li><li><strong>Reply to query</strong>: Post responses and follow-up questions in an ongoing support thread.</li></ul><h3 id="_12-shippings" tabindex="-1"><a class="header-anchor" href="#_12-shippings"><span>12. Shippings</span></a></h3><ul><li><strong>View shipping</strong>: View configured shipping methods and rates.</li><li><strong>Manage shipping zones</strong>: Create, edit, and configure custom vendor shipping zones and delivery rates.</li><li><strong>Manage shipping classes</strong>: Assign and organize product shipping classes.</li></ul><h3 id="_13-admin-news" tabindex="-1"><a class="header-anchor" href="#_13-admin-news"><span>13. Admin News</span></a></h3><ul><li><strong>View news list</strong>: Browse marketplace updates and announcements published by the admin.</li><li><strong>View news details</strong>: Read the full text of policy changes and marketplace news articles.</li></ul><h3 id="_14-storefront-design" tabindex="-1"><a class="header-anchor" href="#_14-storefront-design"><span>14. Storefront Design</span></a></h3><ul><li><strong>View storefront layouts and variations</strong>: Preview custom shop page designs and themes.</li><li><strong>Customize and publish storefront designs</strong>: Customize layout blocks, visual elements, and publish shop designs.</li></ul><div class="hint-container tip"><p class="hint-container-title">Fast Selection with &quot;Select all&quot;</p><p>Each capability card includes a <strong>Select all</strong> button in its header. Clicking this button instantly selects all permissions in that card. Clicking it again deselects all items, allowing vendors to quickly configure access.</p></div><hr><h2 id="staff-member-dashboard-experience" tabindex="-1"><a class="header-anchor" href="#staff-member-dashboard-experience"><span>Staff Member Dashboard Experience</span></a></h2><p>Once a staff member logs into the marketplace using their credentials:</p><ol><li><strong>Dynamic Navigation</strong>: The seller dashboard menu automatically adjusts. The staff member only sees menu links for sections they are permitted to view.</li><li><strong>Action Restrictions</strong>: If a staff member has permission to <em>View orders</em> but not <em>Refund order</em>, the refund action buttons remain hidden and inaccessible.</li><li><strong>Strict Account Isolation</strong>: Staff members cannot access the primary vendor&#39;s bank account details, payout withdrawal forms, or administrative marketplace settings.</li><li><strong>Staff Management Restriction</strong>: Staff members cannot create, edit, or delete other staff accounts. Only the primary vendor can manage sub-accounts.</li></ol><hr><h2 id="staff-quotas-and-admin-delegations" tabindex="-1"><a class="header-anchor" href="#staff-quotas-and-admin-delegations"><span>Staff Quotas and Admin Delegations</span></a></h2><p>Please keep the following operational rules in mind:</p><ul><li><strong>Admin Delegatable Scope</strong>: Vendors can only grant permissions that the marketplace administrator has enabled in the global delegatable capabilities list. If an admin turns off a specific capability globally, that permission is disabled for all staff.</li><li><strong>Maximum Staff Limit</strong>: The marketplace administrator may set a maximum number of staff accounts allowed per vendor (e.g., up to 5 assistants). If the limit is reached, the vendor must remove an existing assistant before adding a new one.</li></ul><hr><h2 id="vendor-staff-quick-reference-summary" tabindex="-1"><a class="header-anchor" href="#vendor-staff-quick-reference-summary"><span>Vendor Staff Quick Reference Summary</span></a></h2><p>The following table provides a quick summary of the staff management workflow:</p><table><thead><tr><th style="text-align:left;">Screen / Step</th><th style="text-align:left;">Action Button</th><th style="text-align:left;">Key Inputs</th><th style="text-align:left;">Outcome</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Staff List</strong> (<code>/seller/vendor-staff/</code>)</td><td style="text-align:left;"><strong>+Add Vendor Staff</strong></td><td style="text-align:left;">None</td><td style="text-align:left;">Opens the Add Vendor Staff form.</td></tr><tr><td style="text-align:left;"><strong>Add Staff</strong> (<code>?section=settings</code>)</td><td style="text-align:left;"><strong>Add Vendor Staff</strong></td><td style="text-align:left;">Name, Email, Capability Checkboxes</td><td style="text-align:left;">Creates a new staff sub-account and sends login details to the assistant.</td></tr><tr><td style="text-align:left;"><strong>Edit Staff</strong> (<code>?section=settings&amp;staff_id=XX</code>)</td><td style="text-align:left;"><strong>Update Vendor Staff</strong></td><td style="text-align:left;">Name (editable), Email (read-only), Capability Checkboxes</td><td style="text-align:left;">Immediately updates the staff member&#39;s name and assigned permissions.</td></tr><tr><td style="text-align:left;"><strong>Delete Staff</strong> (Staff List Modal)</td><td style="text-align:left;"><strong>Yes, remove</strong></td><td style="text-align:left;">Confirmation click</td><td style="text-align:left;">Permanently deletes the sub-account and revokes store access.</td></tr><tr><td style="text-align:left;"><strong>Form Cancellation</strong></td><td style="text-align:left;"><strong>Cancel</strong></td><td style="text-align:left;">None</td><td style="text-align:left;">Aborts current changes and returns to the staff directory list.</td></tr></tbody></table><hr><h2 id="vendor-staff-endpoint-url" tabindex="-1"><a class="header-anchor" href="#vendor-staff-endpoint-url"><span>Vendor Staff Endpoint URL</span></a></h2><p>Vendors access this management interface using the dedicated front-end endpoint:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">https://example.com/seller/vendor-staff/</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><em>Note: Marketplace administrators can customize this endpoint slug and title under <strong>Marketplace &gt; Settings &gt; Endpoints</strong>. For more details, see <a href="/documentation/configuration-endpoints" target="_blank" rel="noopener noreferrer">Endpoints Configuration</a>.</em></p>',85)]))}]]),g=JSON.parse('{"path":"/documentation/vendor-staff.html","title":"Vendor Staff – Seller / Vendor Guide","lang":"en-US","frontmatter":{"title":"Vendor Staff – Seller / Vendor Guide","description":"Learn how vendors can add sub-users, invite team members, delegate task-specific permissions, and manage staff operations in WooCommerce Multi-Vendor Marketplace.","head":[["meta",{"name":"keywords","content":"woocommerce vendor staff, vendor sub accounts, seller assistant management, vendor staff permissions, marketplace store managers, delegatable staff roles, seller team members, add vendor staff woocommerce, manage seller permissions"}],["meta",{"property":"og:title","content":"Vendor Staff – Seller / Vendor Guide | WooCommerce Multi-Vendor Marketplace"}],["meta",{"property":"og:description","content":"Learn how vendors can add sub-users, invite team members, delegate task-specific permissions, and manage staff operations in WooCommerce Multi-Vendor Marketplace."}],["meta",{"property":"og:type","content":"article"}]]},"headers":[{"level":2,"title":"Why Use Vendor Staff?","slug":"why-use-vendor-staff","link":"#why-use-vendor-staff","children":[]},{"level":2,"title":"Managing Vendor Staff","slug":"managing-vendor-staff","link":"#managing-vendor-staff","children":[{"level":3,"title":"Staff Directory Table","slug":"staff-directory-table","link":"#staff-directory-table","children":[]},{"level":3,"title":"Adding a New Staff Member","slug":"adding-a-new-staff-member","link":"#adding-a-new-staff-member","children":[]},{"level":3,"title":"Editing Staff Settings and Permissions","slug":"editing-staff-settings-and-permissions","link":"#editing-staff-settings-and-permissions","children":[]},{"level":3,"title":"Removing a Staff Member","slug":"removing-a-staff-member","link":"#removing-a-staff-member","children":[]}]},{"level":2,"title":"Granular Permissions Matrix","slug":"granular-permissions-matrix","link":"#granular-permissions-matrix","children":[{"level":3,"title":"1. Seller Dashboard","slug":"_1-seller-dashboard","link":"#_1-seller-dashboard","children":[]},{"level":3,"title":"2. Products","slug":"_2-products","link":"#_2-products","children":[]},{"level":3,"title":"3. Select And Sell","slug":"_3-select-and-sell","link":"#_3-select-and-sell","children":[]},{"level":3,"title":"4. Bulk Upload","slug":"_4-bulk-upload","link":"#_4-bulk-upload","children":[]},{"level":3,"title":"5. Orders","slug":"_5-orders","link":"#_5-orders","children":[]},{"level":3,"title":"6. Transactions","slug":"_6-transactions","link":"#_6-transactions","children":[]},{"level":3,"title":"7. Vacation","slug":"_7-vacation","link":"#_7-vacation","children":[]},{"level":3,"title":"8. Shop Followers","slug":"_8-shop-followers","link":"#_8-shop-followers","children":[]},{"level":3,"title":"9. Notifications","slug":"_9-notifications","link":"#_9-notifications","children":[]},{"level":3,"title":"10. My Profile","slug":"_10-my-profile","link":"#_10-my-profile","children":[]},{"level":3,"title":"11. Ask Admin","slug":"_11-ask-admin","link":"#_11-ask-admin","children":[]},{"level":3,"title":"12. Shippings","slug":"_12-shippings","link":"#_12-shippings","children":[]},{"level":3,"title":"13. Admin News","slug":"_13-admin-news","link":"#_13-admin-news","children":[]},{"level":3,"title":"14. Storefront Design","slug":"_14-storefront-design","link":"#_14-storefront-design","children":[]}]},{"level":2,"title":"Staff Member Dashboard Experience","slug":"staff-member-dashboard-experience","link":"#staff-member-dashboard-experience","children":[]},{"level":2,"title":"Staff Quotas and Admin Delegations","slug":"staff-quotas-and-admin-delegations","link":"#staff-quotas-and-admin-delegations","children":[]},{"level":2,"title":"Vendor Staff Quick Reference Summary","slug":"vendor-staff-quick-reference-summary","link":"#vendor-staff-quick-reference-summary","children":[]},{"level":2,"title":"Vendor Staff Endpoint URL","slug":"vendor-staff-endpoint-url","link":"#vendor-staff-endpoint-url","children":[]}],"git":{},"filePathRelative":"documentation/vendor-staff.md"}')}}]);